<?php
/**
 * MedCare System - Lightweight dashboard charts
 *
 * Charts are plain HTML + CSS generated by PHP (no chart library, no internet
 * needed). Every chart has hover/keyboard tooltips (data-tip) and a
 * "View as table" fallback so values never depend on colour alone.
 */

if (!function_exists('chart_e')) {
    function chart_e($value) {
        return htmlspecialchars((string)($value ?? ''), ENT_QUOTES, 'UTF-8');
    }
}

/**
 * Round an axis maximum up to a "nice" number (1, 2, 5, 10 ...).
 */
function chart_nice_max($max) {
    $max = max(1, (float)$max);
    if ($max <= 5) {
        return (int)ceil($max);
    }
    $exp = pow(10, floor(log10($max)));
    foreach ([1, 2, 2.5, 5, 10] as $m) {
        if ($m * $exp >= $max) {
            return (int)ceil($m * $exp);
        }
    }
    return (int)ceil($max);
}

/**
 * Small "View as table" block shown under every chart.
 */
function chart_table(array $headers, array $rows) {
    $html = '<details class="viz-table"><summary>View as table</summary><table><thead><tr>';
    foreach ($headers as $h) {
        $html .= '<th scope="col">' . chart_e($h) . '</th>';
    }
    $html .= '</tr></thead><tbody>';
    foreach ($rows as $row) {
        $html .= '<tr>';
        foreach ($row as $i => $cell) {
            $html .= $i === 0 ? '<th scope="row">' . chart_e($cell) . '</th>' : '<td>' . chart_e($cell) . '</td>';
        }
        $html .= '</tr>';
    }
    return $html . '</tbody></table></details>';
}

/**
 * Vertical column chart (one series).
 * $points: [['label' => 'Mon', 'sub' => '21', 'value' => 3, 'tip' => 'Mon, Oct 21', 'highlight' => false], ...]
 */
function chart_columns(array $points, $unit_singular, $unit_plural, $aria_label) {
    $max = 0;
    foreach ($points as $p) {
        $max = max($max, (int)$p['value']);
    }
    $axis_max = chart_nice_max($max);
    $ticks = $axis_max <= 5 ? range(0, $axis_max) : [0, $axis_max / 2, $axis_max];

    $html = '<div class="viz-columns" role="img" aria-label="' . chart_e($aria_label) . '">';
    $html .= '<div class="viz-columns-axis" aria-hidden="true">';
    foreach (array_reverse($ticks) as $t) {
        $html .= '<span style="bottom:' . round($t / $axis_max * 100, 2) . '%">' . chart_e(rtrim(rtrim(number_format($t, 1), '0'), '.')) . '</span>';
    }
    $html .= '</div><div class="viz-columns-plot"><div class="viz-gridlayer" aria-hidden="true">';
    foreach ($ticks as $t) {
        $html .= '<span class="viz-gridline' . ($t == 0 ? ' is-base' : '') . '" style="bottom:' . round($t / $axis_max * 100, 2) . '%"></span>';
    }
    $html .= '</div>';
    foreach ($points as $p) {
        $v = (int)$p['value'];
        $pct = round($v / $axis_max * 100, 2);
        $tip = $v . ' ' . ($v === 1 ? $unit_singular : $unit_plural) . '|' . $p['tip'];
        $html .= '<div class="viz-col' . (!empty($p['highlight']) ? ' is-highlight' : '') . '" tabindex="0" data-tip="' . chart_e($tip) . '">';
        $html .= '<div class="viz-col-track">';
        if ($v > 0) {
            $html .= '<div class="viz-col-bar" style="height:' . $pct . '%">';
            if (!empty($p['highlight'])) {
                $html .= '<span class="viz-col-value">' . $v . '</span>';
            }
            $html .= '</div>';
        }
        $html .= '</div>';
        $html .= '<div class="viz-col-label"><span>' . chart_e($p['label']) . '</span><small>' . chart_e($p['sub'] ?? '') . '</small></div>';
        $html .= '</div>';
    }
    return $html . '</div></div>';
}

/**
 * Horizontal bar chart.
 * $rows: [['label' => 'Pending', 'value' => 3, 'color' => 'var(--viz-series-1)', 'icon' => '', 'target' => null, 'note' => ''], ...]
 * If a row has 'target', a thin marker is drawn at that value (e.g. minimum stock level).
 */
function chart_bars(array $rows, $unit_singular, $unit_plural, $aria_label, $show_percent = false) {
    $max = 0;
    $total = 0;
    foreach ($rows as $r) {
        $max = max($max, (int)$r['value'], (int)($r['target'] ?? 0));
        $total += (int)$r['value'];
    }
    $axis_max = max(1, $max);

    $html = '<div class="viz-bars" role="img" aria-label="' . chart_e($aria_label) . '">';
    foreach ($rows as $r) {
        $v = (int)$r['value'];
        $pct = round($v / $axis_max * 100, 2);
        $value_text = number_format($v);
        if ($show_percent && $total > 0) {
            $value_text .= ' <small>' . round($v / $total * 100) . '%</small>';
        }
        if (isset($r['target'])) {
            $value_text .= ' <small>/ ' . (int)$r['target'] . '</small>';
        }
        $tip = $v . ' ' . ($v === 1 ? $unit_singular : $unit_plural) . '|' . $r['label'];
        if (isset($r['target'])) {
            $tip .= ' · minimum ' . (int)$r['target'];
        }
        $html .= '<div class="viz-bar-row" tabindex="0" data-tip="' . chart_e($tip) . '">';
        $html .= '<div class="viz-bar-label">' . (!empty($r['icon']) ? '<span class="viz-status-icon" aria-hidden="true">' . $r['icon'] . '</span>' : '') . '<span>' . chart_e($r['label']) . '</span></div>';
        $html .= '<div class="viz-bar-track">';
        if ($v > 0) {
            $html .= '<div class="viz-bar" style="width:' . max($pct, 1.5) . '%;background:' . $r['color'] . '"></div>';
        }
        if (isset($r['target'])) {
            $html .= '<span class="viz-bar-target" style="left:' . round((int)$r['target'] / $axis_max * 100, 2) . '%" aria-hidden="true"></span>';
        }
        $html .= '</div>';
        $html .= '<div class="viz-bar-value">' . $value_text . '</div>';
        $html .= '</div>';
    }
    return $html . '</div>';
}
